assemble.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
function norm(s) { s = String(s).trim(); try { s = s.normalize('NFKC'); } catch (e) {} return s.toLowerCase(); }
const TOMB = '（舊管線產物';
function usable(e) {
  if (!e || typeof e !== 'object') return false;
  if (!e.page_name) return false;
  const c = String(e.content || '');
  if (!c.trim() || c.indexOf(TOMB) === 0 || c.indexOf('（重複頁') === 0) return false;
  if (e.metadata_json) {
    try {
      const m = JSON.parse(e.metadata_json);
      if (m && m.status === 'deprecated') return false;
      // 🔴 地圖自己產的摘要 block（kind=library_map）不是使用者的原文。
      //   實測（2026-08-17，youlin 真資料）：不濾的話它們會**霸佔出處清單前段**
      //   ——因為它們的內容就是庫名＋核心實體，字面重疊分數天生最高，
      //   於是 `library-map:kb` 這種內部頁名會被當成「參照原文位置」印給使用者看，
      //   而 leo 要的正是「**會看到他的參照原文位置檔名**」。印內部產物＝答非所問。
      //   同一個口徑 kbdb 那側早就有了（liveEntryCountsByLibrary 註解：
      //   「地圖不該把自己算進地圖裡」），只是 GET /entries 是通用列表端點不做這個排除
      //   ⇒ 排除留在讀端。它們的內容並沒有消失：已經以「子庫目錄」的形式在 prompt 最前面。
      if (m && m.kind === 'library_map') return false;
    } catch (err) {}
  }
  return true;
}
function metaOf(e) { if (e && e.metadata_json) { try { return JSON.parse(e.metadata_json) || {}; } catch (err) {} } return {}; }
function srcOf(e) { return String(metaOf(e).source || ''); }
function libOf(e) { return String(metaOf(e).library || 'general'); }
// machineOf（`inkstone/mira#6`）：這則知識的原稿在**哪一台機器**上。
// 回一個「要不要放這兩個 key」的物件：**缺值就一個 key 都不放**，不塞空字串——
// 前端的判準是「有沒有值」，空字串會讓「未知來源」變成一個看起來有名字的東西。
// 舊資料（改版前灌的）本來就沒有這一格，那就是誠實的「未知來源」。
function machineOf(e) {
  const m = metaOf(e);
  const id = String(m.machine || '');
  if (!id) return {};
  const label = String(m.machine_label || '') || id;
  return { machine: id, machine_label: label };
}
// 把 machineOf 的結果併進一個既有物件（三處投影共用一份，不要各寫各的）。
function withMachine(obj, e) {
  const mm = machineOf(e);
  if (mm.machine) { obj.machine = mm.machine; obj.machine_label = mm.machine_label; }
  return obj;
}
function chunkIdx(src) { const m = /#(\d+)$/.exec(src); return m ? parseInt(m[1], 10) : 999; }
function toksOf(text) {
  const t = norm(text);
  const out = new Set();
  for (const w of (t.match(/[a-z0-9]{2,}/g) || [])) out.add(w);
  const cjk = t.replace(/[^一-鿿]/g, ' ');
  for (const seg of cjk.split(/\s+/)) { for (let i = 0; i + 1 < seg.length; i++) out.add(seg.slice(i, i + 2)); }
  return out;
}

const question = String(input.question || '');
const sel = parse(input.sel_body) || {};
const route = String(sel.route || 'all');
const selLibs = Array.isArray(sel.libraries) ? sel.libraries : [];
const indexes = Array.isArray(sel.indexes) ? sel.indexes : [];

// ── 館藏目錄：一律進 prompt（「有哪些子庫、各自談什麼」的答案在這裡）──
let catalog = '';
if (indexes.length) {
  catalog = '本知識庫的子庫目錄（共 ' + indexes.length + ' 個）：\n';
  for (const ix of indexes) {
    const bits = [];
    if (typeof ix.entry_count === 'number') bits.push(ix.entry_count + ' 筆內容');
    if (typeof ix.triplet_count === 'number') bits.push(ix.triplet_count + ' 條關聯');
    // narrative 還沒寫進來的庫，用重點實體代替——不編造，也不留白
    const desc = (ix.narrative && String(ix.narrative).trim())
      ? String(ix.narrative).trim()
      : ((Array.isArray(ix.top_entities) && ix.top_entities.length)
          ? ('主要談：' + ix.top_entities.join('、'))
          : '（這個子庫還沒有內容摘要）');
    catalog += '- ' + ix.library + '（' + bits.join('・') + '）：' + desc + '\n';
  }
  catalog += '\n';
}

// ── 命中子庫與命中實體（graph 的話語）──
let hitTxt = '';
const facts = [];
if (selLibs.length) {
  hitTxt = '這個問題從知識圖譜比對到下列子庫（' +
    (route === 'graph' ? '依三元組實體命中' : '依子庫索引比對') + '）：\n';
  for (const l of selLibs) {
    const ents = Array.isArray(l.matched_entities) ? l.matched_entities : [];
    hitTxt += '- ' + l.library + (ents.length ? '（命中實體：' + ents.join('、') + '）' : '') + '\n';
    for (const e of ents) { const line = e + ' 出現在子庫 ' + l.library; if (facts.indexOf(line) === -1) facts.push(line); }
  }
  hitTxt += '\n';
}

// ── 選中子庫的原文 ──
//
// 🔴 `inkstone/mira#6`（總管 2026-08-18 裁定）：**內容留一份、出處記多台**。
//   leo 的原話就是判準——「就算是我一個人的，我有 2 台電腦、1 台 NAS，
//   **它會告訴我原稿去哪裡找，但知識全在總庫**」：
//     「知識全在總庫」        → 餵給 LLM 的內容去重是對的，留一份
//     「告訴我原稿去哪裡找」  → 出處不能去重，所有持有該原稿的機器都要看得見
//   這本來就是分開的兩層，以前被綁在同一個去重動作上才會互相打架。
//
//   這道去重的鍵是「頁名＋內容」。同一份檔同步到兩台、內容一模一樣時，
//   第二台**整筆**在這裡就被丟掉 ⇒ 它的原稿位置在下游（sources／pages_read）
//   再也長不回來。這是本題三處去重裡最上游的一處，所以下游那兩處各自修好了，
//   送到前端的仍然只有一台——它們拿不到一個已經不存在的東西。
//
//   ⇒ 內容照舊只留一份（同樣的文字餵兩次只是燒掉 8000 字預算），
//     但把「還有哪幾台也持有這一份」記在被留下的那一筆身上，供出處投影使用。
//
//   三條收斂規則（**刻意做成與到達順序無關**——「先到的那一台贏」正是本票在修的病，
//   不可以在修它的時候又引進一個新的順序相依）：
//     ① 說不出機器的那一筆（舊資料）**不會**變成第二個出處——不知道就是不知道，
//        編一個「未知來源」列出來只是製造一列沒有資訊的東西。
//     ② 同一台機器的重複片段不是第二個出處（同一把 machine 只算一次）。
//     ③ 代表那一筆若說不出機器、而後來的說得出 ⇒ **換它當代表**。
//        否則同一份資料會因為 KBDB 回傳順序不同而時而一列、時而兩列。
//   ⇒ **`blocks` 的筆數與改版前完全相同**（一個內容群仍然只留一筆），
//     所以下面的 IDF 統計與頁面排序一個數字都不會變；變的只有出處投影。
const raw = ((parse(input.pages_body) || {}).entries) || [];
const groups = new Map();
const order = [];
for (const e of raw) {
  if (!usable(e)) continue;
  const k = e.page_name + '|' + String(e.content).trim();
  const mk = String(metaOf(e).machine || '');
  const g = groups.get(k);
  if (!g) {
    groups.set(k, { rep: e, extras: [], machines: mk ? [mk] : [] });
    order.push(k);
    continue;
  }
  if (!mk) continue;                                  // ① 說不出是哪一台
  if (g.machines.indexOf(mk) !== -1) continue;        // ② 同一台的重複片段
  if (!g.machines.length) { g.rep = e; g.machines.push(mk); continue; }   // ③ 換代表
  g.machines.push(mk);
  g.extras.push(e);
}
const blocks = [];
const alsoOn = new Map();
for (const k of order) {
  const g = groups.get(k);
  blocks.push(g.rep);
  if (g.extras.length) alsoOn.set(g.rep, g.extras);
}
// 一筆 block 的所有出處＝自己 ＋ 內容一模一樣、被上面併掉的其他機器。
// 回的是**原始 entry**，所以 srcOf／libOf／withMachine 三個既有函式照用，
// 不為了這件事另立第二套投影寫法。
function originsOf(e) { return [e].concat(alsoOn.get(e) || []); }
// 庫內排序（不是檢索）：IDF 字面重疊決定哪幾頁先進預算
const qToks = toksOf(question);
const N = blocks.length || 1;
const df = new Map();
const bToks = [];
for (const e of blocks) { const ts = toksOf(e.content); bToks.push(ts); for (const t of ts) df.set(t, (df.get(t) || 0) + 1); }
const pageScore = new Map();
blocks.forEach(function (e, i) {
  let sc = 0;
  for (const t of qToks) if (bToks[i].has(t)) sc += Math.log(1 + N / (df.get(t) || 1));
  pageScore.set(e.page_name, Math.max(pageScore.get(e.page_name) || 0, sc));
});
const pages = Array.from(new Set(blocks.map(function (e) { return e.page_name; })))
  .sort(function (a, b) { return (pageScore.get(b) || 0) - (pageScore.get(a) || 0); });

// 預算 8000 字，範圍已收斂 ⇒ 可以收下多頁（v3 只敢收 1～2 頁，因為它是從全庫挑）
let budget = 8000;
const ctxBlocks = [];
const pagesRead = [];
for (const page of pages) {
  if (budget <= 0) break;
  const es = blocks.filter(function (e) { return e.page_name === page; });
  es.sort(function (x, y) { return chunkIdx(srcOf(x)) - chunkIdx(srcOf(y)); });
  // 🔴 `inkstone/mira#6`（retrieval-tree-and-breadcrumb 2026-08-18 在 stage 實測抓到）：
  //   這裡原本是「一個 page_name 一筆」、而且拿 es[0] 的 source ⇒ 同一頁同時存在於
  //   兩台機器時，pages_read **只會留下先到的那一台**，另一台的原稿位置就此消失。
  //   那正好抵銷掉本票要做的事（答得出原稿在哪台機器）。
  //   ⇒ 分組鍵改成 (頁, 機器)。沒有 machine 的舊資料一律落在同一組（鍵＝空字串），
  //   行為與改版前一字不差。
  const perMachine = new Map();
  for (const e of es) {
    if (budget <= 0) break;
    let c = String(e.content);
    if (c.length > budget) c = c.slice(0, budget);
    budget -= c.length;
    // `entry` 只在本函式內部用來回查「這份內容還在哪幾台上」（sources 投影要用），
    // 它不會出現在回應裡：ctxBlocks 只被拿來組 ctx 字串與 sources。
    ctxBlocks.push(withMachine({ page: page, content: c, source: srcOf(e), library: libOf(e), entry: e }, e));
    // 內容只算一次預算（上面 budget 已扣），出處則每台各記一筆。
    for (const o of originsOf(e)) {
      const mk = String(metaOf(o).machine || '');
      const g = perMachine.get(mk);
      if (g) { g.chars += c.length; } else { perMachine.set(mk, { chars: c.length, first: o }); }
    }
  }
  for (const g of perMachine.values()) {
    if (g.chars > 0) pagesRead.push(withMachine({ page: page, library: libOf(g.first), chars: g.chars, source: srcOf(g.first) }, g.first));
  }
}

const sources = [];
ctxBlocks.forEach(function (bk, i) {
  // machine 從 ctxBlocks 帶過來（它上面已經 withMachine 過），不重解一次 metadata。
  const out = { n: i + 1, mode: bk.library, page: bk.page, source: bk.source };
  if (bk.machine) { out.machine = bk.machine; out.machine_label = bk.machine_label; }
  sources.push(out);
  // 內容一模一樣、在上游被併掉的其他機器：出處各給一列。
  // 🔴 `n` 沿用同一個編號，**不是漏寫**：它們指的是同一段文字，prompt 裡只出現一次 [n]，
  //   換一個編號會讓 LLM 的引用對不上。前端列出處時不看 n（看 page／source／machine），
  //   引擎那側 `dedupeSourcesByPage` 的鍵是「頁 × 機器」⇒ 這幾列不會被併掉。
  for (const o of (alsoOn.get(bk.entry) || [])) {
    sources.push(withMachine({ n: i + 1, mode: bk.library, page: bk.page, source: srcOf(o) }, o));
  }
});
let ctx = '';
ctxBlocks.forEach(function (bk, i) { ctx += '[' + (i + 1) + '] （出自子庫《' + bk.library + '》的《' + bk.page + '》）\n' + bk.content + '\n\n'; });

const prompt = '你是企業知識庫問答助手。只根據下面提供的資料回答，資料裡沒有的不要編造；' +
  '引用原文時標注資料編號如 [1]、[2]。\n\n' +
  catalog + hitTxt +
  '原文片段：\n' + (ctx || '（這次沒有讀入原文片段——若問題可由上面的子庫目錄回答，就用目錄回答）\n') +
  '\n問題：' + question + '\n\n' +
  '輸出規則（嚴格遵守）：不要輸出思考過程或英文草稿，只輸出一行——' +
  '以【答】開頭、用正體中文、一段話；引用原文時帶 [n]，只用子庫目錄回答時不必帶編號；' +
  '資料不足就寫【答】後接「知識庫裡沒有這方面資料」。';

// 前端契約（console-ui/public/portal/index.html retrievalTraceHtml，b48f02b）
const retrieval = {
  route: route,
  vector_used: false,
  libraries_considered: typeof sel.libraries_considered === 'number' ? sel.libraries_considered : indexes.length,
  libraries: selLibs.map(function (l) {
    return { library: l.library, score: l.score, via: l.via, matched_entities: Array.isArray(l.matched_entities) ? l.matched_entities : [] };
  }),
  indexes_read: indexes.map(function (ix) {
    return {
      library: ix.library, narrative: ix.narrative || '', selected: !!ix.selected,
      top_entities: Array.isArray(ix.top_entities) ? ix.top_entities : [],
      triplet_count: ix.triplet_count, entry_count: ix.entry_count
    };
  }),
  pages_read: pagesRead
};

return { success: true, prompt: prompt, sources: sources, graph_facts: facts, retrieval: retrieval, has_ctx: ctxBlocks.length > 0 };

finalize.code:
const answer = String(input.answer == null ? '' : input.answer).trim();
const sources = Array.isArray(input.sources) ? input.sources : [];
const facts = Array.isArray(input.graph_facts) ? input.graph_facts : [];
return {
  success: true,
  answer: answer || '（知識庫裡沒有找到足以回答的資料。）',
  sources: answer ? sources : [],
  graph_facts: facts,
  retrieval: input.retrieval || null
};

pick_stale.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const path = String(input.path || '');
const page = String(input.page_name || '');
const machine = String(input.machine || '');
const kbPrefix = 'kb://' + path + '#';
// 🔴 `inkstone/mira#6`（leo 2026-08-18）：path 是**相對於被監看資料夾**的路徑，
//   所以兩台機器上的 `RFP/design.md` 在這裡長得一模一樣 ⇒ 後同步的那台會把
//   前一台的知識**無聲刪掉**（症狀不是「變兩份」，是前面那份消失）。
//   machine 是唯一分得開它們的那一維。規則照抄 arcrun-rag#46 對 library 的做法：
//   **兩邊都有值時才收緊**——payload 沒帶（舊版 daemon）或卡上沒有（改版前的
//   既有資料）都退回原本的行為，既有資料照樣被同一台機器 upsert 掉，不會突然變兩份。
function machineBlocks(theirs) {
  return machine !== '' && theirs !== '' && theirs !== machine;
}
const ab = parse(input.blocks_body);
const entries = (ab && ab.entries) || [];
const dead_entry = [];
for (const e of entries) {
  let meta = {};
  if (e.metadata_json) { try { meta = JSON.parse(e.metadata_json) || {}; } catch (err) { meta = {}; } }
  const mPath = String(meta.source_path || '');
  const mSrc = String(meta.source || '');
  const hasPath = mPath !== '';
  const hasKbSrc = mSrc.indexOf('kb://') === 0;
  let hit;
  if (hasPath || hasKbSrc) {
    hit = (hasPath && path && mPath === path) || (hasKbSrc && path && mSrc.indexOf(kbPrefix) === 0);
  } else { hit = true; }
  if (hit && machineBlocks(String(meta.machine || ''))) hit = false;
  if (hit && e.id) dead_entry.push({ id: e.id });
}
const ar = parse(input.triplets_body);
const recs = (ar && (ar.records || ar.result)) || [];
const dead_record = [];
for (const r of recs) {
  const v = r.values || r;
  const src = String(v.source_uri || '');
  const subj = String(v.subject || '');
  const rid = r.record_id || r.id;
  if (!rid) continue;
  let hit = (path && src.indexOf('kb://' + path) === 0) || (!src && page && subj === page);
  // 同一條規則用在三元組上（比照 rag_takedown_direct 的 pick_dead_triplets 對 library 的處置）。
  // ⚠️ 這一格要真的生效，triplet template 必須有 machine slot——沒有時 KBDB 會
  //    **靜默丟掉**這個值（record-crud.ts createRecord：writtenSlots 只取 template 有的 slot），
  //    於是三元組永遠讀不到 machine、退回舊行為。補 slot 的正路＝ cypher-executor
  //    的 PORTAL_TEMPLATE_SEEDS（ensurePortalTemplates 會 PATCH 補上，library 當初就是這樣加的）。
  if (hit && machineBlocks(String(v.machine || ''))) hit = false;
  if (hit) dead_record.push({ record_id: rid });
}
return { dead_entry: dead_entry, dead_record: dead_record,
         removed_blocks: dead_entry.length, removed_triplets: dead_record.length };

parse_card.code:
const md = String(input.card == null ? '' : input.card);
const pageName = String(input.page_name || 'unknown');
const srcPath = String(input.path || (pageName + '.md'));
const srcUri = 'kb://' + srcPath;
const lib = String(input.library || 'kb');
// 🔴 `inkstone/mira#6`：machine 是**獨立的一格**，不塞進 source_uri。
//   source_uri 的既有意思是「相對於被監看資料夾的路徑」，portal 的 srcLocalPath()
//   直接把 `kb://` 之後整段當本機相對路徑用（console-ui/public/portal/index.html）——
//   把機器名混進去會讓那條路吐出 `youlinhsieh@Leo-MBA/RFP/design.md` 這種不存在的路徑，
//   而且舊資料的第一段（`kb://RFP/...` 的 RFP）會被誤讀成機器名 ⇒ **憑空長出假機器**。
//   分成獨立欄位就沒有這個猜測：舊資料沒有這一格＝誠實地「未知來源」。
const machine = String(input.machine || '');
const machineLabel = String(input.machine_label || '') || machine;
if (!md.trim()) return { success: false, error: 'card_content 為空' };
const chunks = [];
let cur = [];
for (const line of md.split('\n')) {
  if (/^#{1,6}\s/.test(line) && cur.join('').trim()) { chunks.push(cur.join('\n').trim()); cur = []; }
  cur.push(line);
}
if (cur.join('').trim()) chunks.push(cur.join('\n').trim());
const blocks = chunks.map(function (content, i) {
  return { content: content, page_name: pageName, source: srcUri + '#' + i, source_path: srcPath,
           library: lib, machine: machine, machine_label: machineLabel };
});
const rels = [];
// InkStoneCo#44：#6-#10 改版後,「## 關聯」下面多了「### 內文知識關係」
// 「### 卡片關係」「### 出處」三個 H3 子區。舊版界線 (?=\n#|\n---|$) 把任何
// 井字號開頭的行都當成段落結束——遇到緊接在「## 關聯」後的第一個「### ...」
// 子標題就立刻收尾,relSec[1] 只抓到「### 內文知識關係」這一行本身,真正的
// 關係清單（卡片關係／出處那些「主體>>述語>>客體」行）從未被讀到,parse_card
// 只剩最後機械補的 part_of 一條會進 kbdb（實測：4 條卡上宣稱的關係只落地 1 條）。
// 修法：邊界只認「下一個 H1／H2」（1-2 個 # 後面接空白,且不是第 3 個 #),
// 不再被巢狀的 H3 子標題提前打斷；沒有下一個 H1/H2 時仍讀到檔尾或 ---。
const relSec = /##\s*關聯\s*\n([\s\S]*?)(?=\n#{1,2}(?!#)\s|\n---|$)/.exec(md);
if (relSec) {
  for (const line of relSec[1].split('\n')) {
    const m = /^\s*(?:[-*]\s*)?(.+?)\s*>>\s*(.+?)\s*>>\s*(.+?)\s*$/.exec(line);
    if (!m) continue;
    rels.push({ subject: m[1], predicate: m[2], object: m[3], source_uri: srcUri, status: 'active', library: lib, machine: machine });
  }
}
rels.push({ subject: pageName, predicate: 'part_of', object: 'knowledge-base', source_uri: srcUri, status: 'active', library: lib, machine: machine });
return { success: true, blocks: blocks, block_count: blocks.length, rels: rels, rel_count: rels.length, page_name: pageName };

prep.code:
const page = String(input.page_name == null ? '' : input.page_name).trim();
if (!page) return { success: false, error: 'rag_takedown_direct 缺 page_name' };
const path = String(input.path || (page + '.md'));
// library（arcrun-rag#46）：選填。舊版 daemon 不會送，此時維持原本只看 path 的行為。
const library = String(input.library == null ? '' : input.library).trim();
// machine（`inkstone/mira#6`，leo 2026-08-18）：與 library 同一條規則、同一個理由，
// 只是差一層——library 分得開「同一台機器的兩個資料夾」，machine 分得開「兩台機器」。
// 選填：舊版 daemon 不送，此時行為與從前一字不差。
const machine = String(input.machine == null ? '' : input.machine).trim();
return { success: true, page_name: page, page_enc: encodeURIComponent(page),
         path: path, source_uri: 'kb://' + path, library: library, machine: machine };

build_deprecations.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const a = parse(input.blocks_body);
const entries = (a && a.entries) || [];
const path = String(input.path || '');
const lib = String(input.library || '');
const mach = String(input.machine || '');
const kbPrefix = 'kb://' + path + '#';
const dead_entries = [];
for (const e of entries) {
  let meta = {};
  if (e.metadata_json) { try { meta = JSON.parse(e.metadata_json) || {}; } catch (err) { meta = {}; } }
  // 2026-08-05 改真刪後拿掉「跳過已 deprecated」：那些舊垃圾正是要清的對象，
  // 留著跳過等於永遠清不掉（實測 youlin 374 blocks 裡有 23 筆）。
  const mPath = String(meta.source_path || '');
  const mSrc = String(meta.source || '');
  const hasPath = mPath !== '';
  const hasKbSrc = mSrc.indexOf('kb://') === 0;
  let hit;
  if (hasPath || hasKbSrc) {
    hit = (hasPath && path && mPath === path) || (hasKbSrc && path && mSrc.indexOf(kbPrefix) === 0);
  } else {
    hit = true;
  }
  // arcrun-rag#46：library 兩邊都有才比；不一致＝別的資料夾的同名檔，不准動。
  const mLib = String(meta.library || '');
  if (hit && lib !== '' && mLib !== '' && mLib !== lib) hit = false;
  // `inkstone/mira#6`：machine 同一條規則（兩邊都有才收緊）。少了這一維，
  // 「A 機器刪掉 notes.md」會把 B 機器上還活著的 notes.md 一起殺掉。
  const mMachine = String(meta.machine || '');
  if (hit && mach !== '' && mMachine !== '' && mMachine !== mach) hit = false;
  if (!hit) continue;
  dead_entries.push({ id: e.id });   // 真刪只需要 id
}
return { success: true, dead_entries: dead_entries, dead_count: dead_entries.length };

pick_dead_triplets.code:
let body = input.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
let records = (body && Array.isArray(body.records)) ? body.records : [];
const page = String(input.page_name || '');
const srcUri = String(input.source_uri || '');
const lib = String(input.library || '');
const mach = String(input.machine || '');
const dead_records = [];
for (const r of records) {
  const v = (r && typeof r === 'object' && r.values && typeof r.values === 'object') ? r.values : null;
  // 2026-08-05：不再跳過 deprecated（改真刪後那些正是要清的舊垃圾）。
  if (!v || !r.record_id) continue;
  const vSrc = typeof v.source_uri === 'string' ? v.source_uri : '';
  let hit = vSrc !== '' ? (srcUri !== '' && vSrc === srcUri) : (v.subject === page);
  // arcrun-rag#46：與 build_deprecations 同一條規則——兩個資料夾各有同名同相對
  // 路徑的檔時，source_uri 也會完全相同，library 是唯一分得開它們的那一維。
  const vLib = typeof v.library === 'string' ? v.library : '';
  if (hit && lib !== '' && vLib !== '' && vLib !== lib) hit = false;
  // `inkstone/mira#6`：machine 同一條規則。⚠️ triplet template 沒有 machine slot 的
  // 實例，這一格永遠是空字串（KBDB 靜默丟掉未宣告的 slot）⇒ 退回舊行為，不會誤殺，
  // 但也擋不住跨機器連坐。補 slot 走 PORTAL_TEMPLATE_SEEDS（library 當初的那條路）。
  const vMachine = typeof v.machine === 'string' ? v.machine : '';
  if (hit && mach !== '' && vMachine !== '' && vMachine !== mach) hit = false;
  if (!hit) continue;
  dead_records.push({ record_id: r.record_id });
}
return { success: true, dead_records: dead_records, count: dead_records.length };
